// Pages opened from a local copy (file://) cannot fetch() their own JSON files, so method
// help (tooltips.js) and the Method Finder went missing there. Each now reads a classic-
// script copy on file:// (generated by tools/fileproto/build-file-data.cjs). These tests
// pin every copy to its JSON so the two cannot drift. Regenerate with:
//   node tools/fileproto/build-file-data.cjs
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import vm from 'node:vm';

const root = new URL('../../../../', import.meta.url);
const read = (rel) => readFileSync(new URL(rel, root), 'utf8');
function loadCopy(rel, name) {
  const ctx = { window: {} };
  vm.runInNewContext(read(rel), ctx);
  // Plain objects from this realm (vm objects carry another realm's prototypes).
  return JSON.parse(JSON.stringify(ctx.window[name]));
}

test('hub/shared/glossary-data.js carries every glossary JSON file, equal as parsed data', () => {
  const files = readdirSync(new URL('hub/shared/', root)).filter((f) => /^glossary(\.[a-z]{2})?\.json$/.test(f)).sort();
  assert.ok(files.includes('glossary.json') && files.length >= 2, 'expected the glossary JSON files');
  const data = loadCopy('hub/shared/glossary-data.js', 'ALM_GLOSSARY_FILES');
  assert.deepEqual(Object.keys(data).sort(), files);
  for (const f of files) assert.deepEqual(data[f], JSON.parse(read('hub/shared/' + f)), f + ' drifted from glossary-data.js');
});

test('finder/decision-tree-data.js equals finder/decision-tree.json', () => {
  assert.deepEqual(loadCopy('finder/decision-tree-data.js', 'ALM_FINDER_TREE'), JSON.parse(read('finder/decision-tree.json')), 'decision tree drifted');
});

test('the pages read the copies on file:// only', () => {
  const tips = read('hub/shared/tooltips.js'), finder = read('finder/index.html');
  assert.ok(tips.includes("location.protocol === 'file:'") && tips.includes('glossary-data.js'), 'tooltips.js has no file:// branch');
  assert.ok(finder.includes("location.protocol === 'file:'") && finder.includes('decision-tree-data.js'), 'finder has no file:// branch');
});
